import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

export const AUTOMATION_ACTIONS: Record<AutomationActionType, AutomationActionDef> = {
	// ─── Mensajería ─────────────────────────────────────────────────────────────

	send_message: {
		key: "send_message",
		category: "message",
		label: "Enviar un mensaje",
		description: "Publica un mensaje en el canal que elijas.",
		requires: [],
		permission: "SendMessages",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{
				// Mismo juego de modos que el mensaje de bienvenida, y con los mismos
				// valores: quien ya ha configurado uno reconoce el otro, y el módulo
				// puede compartir criterio en vez de tener dos formas de decir lo mismo.
				key: "mode",
				type: "select",
				// OPCIONAL aunque la interfaz lo rellene siempre: obligarlo
				// invalidaría de golpe cualquier automatización guardada antes de que
				// el campo existiera. Ausente se lee como "plain", que es justo lo que
				// esas hacían.
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" },
					{ value: "image", label: "Texto + imagen" },
					{ value: "embed_image", label: "Embed + imagen" }
				]
			},
			{
				key: "content",
				type: "long_text",
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
			// El conmutador va DELANTE de los dos campos que gobierna: primero se
			// elige cómo se monta la imagen y luego sale el control de ese modo.
			// Los dos campos coexisten en los datos —cambiar de modo no borra el
			// otro—, sólo cambia cuál se pinta.
			{
				key: "image_mode",
				type: "select",
				variant: "chips",
				required: false,
				label: "Imagen",
				default: "basic",
				options: [
					{ value: "basic", label: "Modo básico" },
					{ value: "advanced", label: "Modo avanzado" }
				]
			},
			{
				key: "image_url",
				type: "image",
				required: false,
				label: "Imagen",
				hint: "Se sube al CDN del bot.",
				default: ""
			},
			{ key: "image_canvas", type: "image_canvas", required: false, label: "Lienzo", default: null },
			{ key: "embed_title", type: "text", required: false, label: "Título", max: 256, supportsVariables: true, default: "" },
			{
				key: "embed_description",
				type: "long_text",
				required: false,
				label: "Descripción",
				max: 4000,
				supportsVariables: true,
				default: ""
			},
			{ key: "embed_color", type: "color", required: false, label: "Color", default: null },
			{
				// Autopublicado (crosspost). Sólo Discord sabe si el canal es de
				// ANUNCIOS: en uno de texto normal la llamada falla con 50019, así que
				// el aviso va en el hint y el fallo se reporta como fallo de la acción
				// en vez de tragárselo — quien marca esto quiere que se publique.
				key: "crosspost",
				type: "boolean",
				required: false,
				label: "Autopublicarlo",
				hint: "Sólo en canales de ANUNCIOS: lo publica en los servidores que siguen el canal.",
				default: false
			},
			deleteAfterParam
		]
	},

	send_dm: {
		key: "send_dm",
		category: "message",
		label: "Enviar un mensaje directo",
		description: "Escribe por privado a quien disparó la automatización.",
		// Los MD cerrados hacen fallar la acción, y eso es correcto: se registra y
		// las acciones siguientes continúan.
		requires: ["user"],
		params: [
			// Mismos formatos que «Enviar un mensaje»: un MD también admite embed e
			// imagen, y tener dos acciones de mensaje con capacidades distintas
			// obliga a acordarse de cuál puede qué.
			{
				key: "mode",
				type: "select",
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" },
					{ value: "image", label: "Texto + imagen" },
					{ value: "embed_image", label: "Embed + imagen" }
				]
			},
			{
				key: "content",
				type: "long_text",
				// Deja de ser obligatorio: con formato embed el texto puede ir todo en
				// el título y la descripción.
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
			// Mismo orden que en `send_message`: primero el conmutador, luego el
			// control del modo elegido.
			{
				key: "image_mode",
				type: "select",
				variant: "chips",
				required: false,
				label: "Imagen",
				default: "basic",
				options: [
					{ value: "basic", label: "Modo básico" },
					{ value: "advanced", label: "Modo avanzado" }
				]
			},
			{
				key: "image_url",
				type: "image",
				required: false,
				label: "Imagen",
				hint: "Se sube al CDN del bot.",
				default: ""
			},
			{ key: "image_canvas", type: "image_canvas", required: false, label: "Lienzo", default: null },
			{ key: "embed_title", type: "text", required: false, label: "Título", max: 256, supportsVariables: true, default: "" },
			{
				key: "embed_description",
				type: "long_text",
				required: false,
				label: "Descripción",
				max: 4000,
				supportsVariables: true,
				default: ""
			},
			{ key: "embed_color", type: "color", required: false, label: "Color", default: null }
		]
	},

	reply_message: {
		key: "reply_message",
		category: "message",
		label: "Responder al mensaje",
		description: "Contesta en el hilo de respuesta del mensaje que lo disparó.",
		requires: ["message"],
		permission: "SendMessages",
		params: [
			{
				key: "content",
				type: "long_text",
				required: true,
				label: "Respuesta",
				max: 2000,
				supportsVariables: true
			},
			{ key: "mention_author", type: "boolean", required: false, label: "Mencionar al autor", default: false },
			deleteAfterParam
		]
	},

	send_webhook: {
		key: "send_webhook",
		category: "message",
		label: "Enviar por un webhook",
		description: "Publica con el nombre y el avatar que tú decidas.",
		requires: [],
		params: [
			{ key: "webhook_url", type: "text", required: true, label: "URL del webhook", max: 300 },
			{
				key: "content",
				type: "long_text",
				required: true,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true
			},
			{ key: "username", type: "text", required: false, label: "Nombre a mostrar", max: 80, supportsVariables: true, default: "" },
			{ key: "avatar_url", type: "text", required: false, label: "URL del avatar", max: 300, default: "" }
		]
	},

	add_reaction: {
		key: "add_reaction",
		category: "message",
		label: "Añadir una reacción",
		description: "Reacciona al mensaje que disparó la automatización.",
		requires: ["message"],
		permission: "AddReactions",
		params: [{ key: "emoji", type: "emoji", required: true, label: "Emoji" }]
	},

	delete_message: {
		key: "delete_message",
		category: "message",
		label: "Borrar el mensaje",
		description: "Elimina el mensaje que disparó la automatización.",
		requires: ["message"],
		permission: "ManageMessages",
		params: [
			{
				key: "delay",
				type: "duration",
				required: false,
				label: "Esperar antes de borrar",
				hint: "Segundos. 0 = al instante.",
				min: 0,
				max: 3600,
				default: 0
			}
		]
	},

	pin_message: {
		key: "pin_message",
		category: "message",
		label: "Fijar o desfijar el mensaje",
		description: "Ancla el mensaje en su canal.",
		requires: ["message"],
		permission: "ManageMessages",
		params: [
			{
				key: "action",
				type: "select",
				required: true,
				label: "Acción",
				default: "pin",
				options: [
					{ value: "pin", label: "Fijar" },
					{ value: "unpin", label: "Desfijar" }
				]
			}
		]
	},

	crosspost_message: {
		key: "crosspost_message",
		category: "message",
		label: "Autopublicar el mensaje",
		description: "Publica el mensaje en los servidores que siguen el canal de anuncios.",
		requires: ["message"],
		// `ManageMessages` es lo que exige Discord para publicar mensajes AJENOS.
		// Para los propios bastaría `SendMessages`, pero el caso de uso real de
		// esta acción —«todo lo que se escriba en #anuncios se publica solo»— son
		// mensajes de otros, así que el permiso que se pide es el que hace falta
		// de verdad.
		permission: "ManageMessages",
		params: []
	},

	sticky_message: {
		key: "sticky_message",
		category: "message",
		label: "Mensaje fijo abajo (sticky)",
		description: "Mantiene un mensaje siempre el último del canal: borra el anterior y lo vuelve a publicar.",
		// `requires: []` a propósito: el canal se elige aquí, así que la acción
		// vale igual colgada de «envíe un mensaje» (el uso normal) que de un
		// horario, sin que el validador la esconda cuando el disparador no trae
		// canal.
		requires: [],
		permission: "ManageMessages",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{
				key: "mode",
				type: "select",
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" }
				]
			},
			{
				key: "content",
				type: "long_text",
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
			{ key: "embed_title", type: "text", required: false, label: "Título", max: 256, supportsVariables: true, default: "" },
			{
				key: "embed_description",
				type: "long_text",
				required: false,
				label: "Descripción",
				max: 4000,
				supportsVariables: true,
				default: ""
			},
			{ key: "embed_color", type: "color", required: false, label: "Color", default: null },
			{
				key: "delay",
				type: "duration",
				required: false,
				label: "Esperar antes de reponerlo",
				// El mínimo NO es cosmético: reponer en cada mensaje son dos llamadas
				// a Discord por mensaje del canal, y en un canal con movimiento eso
				// agota el cubo del bot y arrastra al resto de módulos. La espera
				// agrupa la ráfaga en una sola reposición.
				hint: "Segundos desde el primer mensaje que lo desplaza. Los mensajes de ese rato se agrupan en una sola reposición.",
				min: 3,
				max: 3600,
				default: 10
			},
			{
				key: "min_messages",
				type: "number",
				required: false,
				label: "Mensajes antes de reponerlo",
				hint: "Se cuentan desde la última vez que se repuso.",
				min: 1,
				max: 100,
				default: 1
			}
		]
	},

	// ─── Roles y miembros ───────────────────────────────────────────────────────

	add_role: {
		key: "add_role",
		category: "member",
		label: "Dar un rol",
		description: "Añade uno o varios roles.",
		requires: ["member"],
		permission: "ManageRoles",
		params: [{ key: "roles", type: "role_list", required: true, label: "Roles" }]
	},

	remove_role: {
		key: "remove_role",
		category: "member",
		label: "Quitar un rol",
		description: "Retira uno o varios roles.",
		requires: ["member"],
		permission: "ManageRoles",
		params: [{ key: "roles", type: "role_list", required: true, label: "Roles" }]
	},

	set_nickname: {
		key: "set_nickname",
		category: "member",
		label: "Cambiar el apodo",
		description: "Renombra al miembro en este servidor.",
		requires: ["member"],
		permission: "ManageNicknames",
		params: [
			{
				key: "nickname",
				type: "text",
				required: true,
				label: "Apodo",
				max: 32,
				supportsVariables: true
			}
		]
	},

	kick_member: {
		key: "kick_member",
		category: "member",
		label: "Expulsar",
		description: "Echa al miembro del servidor; puede volver a entrar.",
		requires: ["member"],
		permission: "KickMembers",
		params: [reasonParam]
	},

	ban_member: {
		key: "ban_member",
		category: "member",
		label: "Banear",
		description: "Prohíbe la entrada al servidor.",
		requires: ["user"],
		permission: "BanMembers",
		params: [
			reasonParam,
			{
				key: "delete_message_seconds",
				type: "select",
				required: false,
				label: "Borrar sus mensajes",
				default: "0",
				options: [
					{ value: "0", label: "No borrar nada" },
					{ value: "3600", label: "De la última hora" },
					{ value: "86400", label: "Del último día" },
					{ value: "604800", label: "De la última semana" }
				]
			}
		]
	},

	timeout_member: {
		key: "timeout_member",
		category: "member",
		label: "Aislar",
		description: "Aplica el aislamiento nativo de Discord.",
		requires: ["member"],
		permission: "ModerateMembers",
		params: [
			{
				key: "duration",
				type: "duration",
				required: true,
				label: "Duración",
				// El tope duro de Discord son 28 días; más allá rechaza la petición.
				hint: "Segundos. El máximo de Discord son 28 días.",
				min: 1,
				max: 2_419_200,
				default: 600
			},
			reasonParam
		]
	},

	// ─── Canales ────────────────────────────────────────────────────────────────

	create_channel: {
		key: "create_channel",
		category: "server",
		label: "Crear un canal",
		description: "Añade un canal nuevo al servidor.",
		requires: [],
		permission: "ManageChannels",
		params: [
			{ key: "name", type: "text", required: true, label: "Nombre", max: 100, supportsVariables: true },
			{
				key: "type",
				type: "select",
				required: true,
				label: "Tipo",
				default: "text",
				options: [
					{ value: "text", label: "Texto" },
					{ value: "voice", label: "Voz" },
					{ value: "forum", label: "Foro" },
					{ value: "stage", label: "Escenario" }
				]
			},
			{ key: "category", type: "channel", required: false, label: "Dentro de la categoría", default: null },
			{ key: "topic", type: "text", required: false, label: "Descripción", max: 1024, supportsVariables: true, default: "" }
		]
	},

	create_thread: {
		key: "create_thread",
		category: "server",
		label: "Crear un hilo",
		description: "Abre un hilo sobre el mensaje que disparó la automatización.",
		requires: ["message"],
		permission: "CreatePublicThreads",
		params: [
			{ key: "name", type: "text", required: true, label: "Nombre del hilo", max: 100, supportsVariables: true },
			{
				key: "auto_archive",
				type: "select",
				required: false,
				label: "Archivar tras",
				default: "1440",
				options: [
					{ value: "60", label: "1 hora" },
					{ value: "1440", label: "1 día" },
					{ value: "4320", label: "3 días" },
					{ value: "10080", label: "1 semana" }
				]
			}
		]
	},

	rename_channel: {
		key: "rename_channel",
		category: "server",
		label: "Renombrar un canal",
		description: "Cambia el nombre de un canal. Con variables sirve de canal contador.",
		// `requires: []` y NO `["channel"]`: exigirlo dejaba la acción fuera del
		// selector en cuanto el disparador no traía canal, y con eso el caso más
		// pedido —el canal que muestra «Miembros: 1.234», que nace de un
		// `member_join`— era IMPOSIBLE de montar. El canal se elige aquí.
		requires: [],
		permission: "ManageChannels",
		params: [
			{
				key: "channel",
				type: "channel",
				required: false,
				label: "Canal",
				hint: "Vacío = el canal donde ocurrió, si el disparador trae uno.",
				default: ""
			},
			{
				key: "name",
				type: "text",
				required: true,
				label: "Nombre",
				// El aviso del límite va aquí porque es la sorpresa más cara de esta
				// acción: Discord sólo admite 2 cambios de nombre por canal cada 10
				// minutos, así que un canal contador NO se actualiza al instante.
				// El módulo lo respeta solo (`claimChannelRename`), pero quien lo
				// configura tiene que saberlo o lo dará por roto.
				hint: "Admite variables: «Miembros: {member_count}». Discord sólo deja renombrar un canal 2 veces cada 10 minutos, así que se actualiza como mucho cada 10 minutos.",
				max: 100,
				supportsVariables: true
			}
		]
	},

	set_slowmode: {
		key: "set_slowmode",
		category: "server",
		label: "Poner modo lento",
		description: "Limita cada cuánto se puede escribir en el canal.",
		requires: ["channel"],
		permission: "ManageChannels",
		params: [
			{
				key: "seconds",
				type: "number",
				required: true,
				label: "Segundos entre mensajes",
				hint: "0 desactiva el modo lento. El máximo de Discord son 6 horas.",
				min: 0,
				max: 21_600,
				default: 5
			}
		]
	},

	set_channel_permission: {
		key: "set_channel_permission",
		category: "server",
		label: "Cambiar permisos de un canal",
		description: "Permite o deniega un permiso a un rol en un canal.",
		requires: [],
		permission: "ManageRoles",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{ key: "role", type: "role", required: true, label: "Rol" },
			{
				key: "permission",
				type: "select",
				required: true,
				label: "Permiso",
				default: "SendMessages",
				options: [
					{ value: "ViewChannel", label: "Ver el canal" },
					{ value: "SendMessages", label: "Enviar mensajes" },
					{ value: "AddReactions", label: "Añadir reacciones" },
					{ value: "Connect", label: "Conectarse (voz)" },
					{ value: "Speak", label: "Hablar (voz)" }
				]
			},
			{
				key: "mode",
				type: "select",
				required: true,
				label: "Ponerlo en",
				default: "deny",
				options: [
					{ value: "allow", label: "Permitido" },
					{ value: "deny", label: "Denegado" },
					{ value: "inherit", label: "Heredado" }
				]
			}
		]
	},

	// ─── Voz ────────────────────────────────────────────────────────────────────

	move_voice: {
		key: "move_voice",
		category: "voice",
		label: "Mover a otro canal de voz",
		description: "Sólo funciona si la persona está conectada a voz.",
		requires: ["member"],
		permission: "MoveMembers",
		params: [
			{
				key: "channel",
				type: "channel",
				required: false,
				label: "Canal de destino",
				hint: "Déjalo vacío para desconectarla de la voz.",
				default: null
			}
		]
	},

	voice_mute: {
		key: "voice_mute",
		category: "voice",
		label: "Silenciar en voz",
		description: "Silencio de servidor. Sólo funciona si está conectada a voz.",
		requires: ["member"],
		permission: "MuteMembers",
		params: [
			{
				key: "mute",
				type: "boolean",
				required: true,
				label: "Silenciar",
				hint: "Desactivado, le quita el silencio.",
				default: true
			}
		]
	},

	// ─── Estadísticas ───────────────────────────────────────────────────────────
	//
	// No actúan sobre Discord —no hay canal que renombrar ni rol que dar—: leen
	// un número y lo guardan en una variable de flujo (`save_as`) para que las
	// acciones de detrás lo usen en sus campos de texto. Por eso no llevan
	// `permission`. Son las dos únicas de esta familia: las que tienen un dato
	// real detrás.

	count_voice_members: {
		key: "count_voice_members",
		category: "stats",
		label: "Contar personas en voz",
		description: "Cuenta cuánta gente hay en un canal de voz, o en todo el servidor.",
		requires: [],
		params: [
			{
				key: "channel",
