84		const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
85		return Object.values(AUTOMATION_ACTIONS).filter((a) => a.requires.every((k) => provided.has(k)));
86	}
87	
88	// ─── Parámetros ───────────────────────────────────────────────────────────────
89	
90	/** Objeto de parámetros inicial de un bloque recién añadido, con sus defaults. */
91	export function buildDefaultParams(params: AutomationParam[]): Record<string, unknown> {
92		const out: Record<string, unknown> = {};
93		for (const param of params) {
94			if (param.default !== undefined) {
95				out[param.key] = param.default;
96				continue;
97			}
98			// Sin default declarado. Los campos que el formulario pinta como lista
99			// necesitan un array desde el principio (si no, el control no sabe qué
100			// renderizar); el resto se deja AUSENTE para que `missing_required` lo cace
101			// si hacía falta. Un `default: []` en un obligatorio no arreglaría nada y
102			// además disfrazaría el hueco — lo vigila `catalog.test.ts`.
103			if (param.type.endsWith("_list") || (param.type === "select" && param.multiple)) out[param.key] = [];
104			else if (param.type === "boolean") out[param.key] = false;
105		}
106		return out;
107	}
108	
109	/** ¿Cuenta como «sin rellenar»? `false` y `0` NO — son valores legítimos. */
110	const isEmpty = (value: unknown): boolean =>
111		value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0);
112	
113	function checkOne(param: AutomationParam, value: unknown, path: string): AutomationIssue[] {
114		const issues: AutomationIssue[] = [];
115		const at = `${path}.${param.key}`;
116		const fail = (code: AutomationIssueCode, message: string) => issues.push({ path: at, code, message });
117	
118		if (isEmpty(value)) {
119			if (param.required) fail("missing_required", `«${param.label}» es obligatorio.`);
120			return issues;
121		}
122	
123		switch (param.type) {
124			case "text":
125			case "long_text":
126			case "emoji":
127			case "counter":
128			case "automation":
129			case "regex":
130			case "color": {
131				if (typeof value !== "string") {
132					fail("invalid_type", `«${param.label}» tiene que ser texto.`);
133					break;
134				}
135				if (param.min !== undefined && value.length < param.min) {
136					fail("out_of_range", `«${param.label}» necesita al menos ${param.min} caracteres.`);
137				}
138				if (param.max !== undefined && value.length > param.max) {
139					fail("out_of_range", `«${param.label}» admite como mucho ${param.max} caracteres.`);
140				}
141				if (param.pattern && !new RegExp(param.pattern).test(value)) {
142					fail("invalid_format", `«${param.label}» no tiene el formato correcto.`);
143				}
144				if (param.type === "counter" && !COUNTER_NAME.test(value)) {
145					fail("invalid_format", `«${param.label}» sólo admite letras, números, guiones y guiones bajos.`);
146				}
147				if (param.type === "color" && !HEX_COLOR.test(value)) {
148					fail("invalid_format", `«${param.label}» tiene que ser un color hexadecimal, por ejemplo #5865F2.`);
149				}
150				if (param.type === "regex") {
151					try {
152						new RegExp(value);
153					} catch {
154						fail("invalid_format", `«${param.label}» no es una expresión regular válida.`);
155					}
156				}
157				break;
158			}
159	
160			case "number":
161			case "duration": {
162				if (typeof value !== "number" || !Number.isFinite(value)) {
163					fail("invalid_type", `«${param.label}» tiene que ser un número.`);
164					break;
165				}
166				if (param.min !== undefined && value < param.min) {
167					fail("out_of_range", `«${param.label}» no puede bajar de ${param.min}.`);
168				}
169				if (param.max !== undefined && value > param.max) {
170					fail("out_of_range", `«${param.label}» no puede pasar de ${param.max}.`);
171				}
172				break;
173			}
174	
175			case "boolean": {
176				if (typeof value !== "boolean") fail("invalid_type", `«${param.label}» tiene que ser sí o no.`);
177				break;
178			}
179	
180			case "channel":
181			case "role":
182			case "user": {
183				if (typeof value !== "string" || !SNOWFLAKE.test(value)) {
184					fail("invalid_format", `«${param.label}» no es un identificador de Discord válido.`);
185				}
186				break;
187			}
188	
189			case "channel_list":
190			case "category_list":
191			case "role_list": {
192				if (!Array.isArray(value)) {
193					fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
194					break;
195				}
196				if (value.some((v) => typeof v !== "string" || !SNOWFLAKE.test(v))) {
197					fail("invalid_format", `«${param.label}» contiene un identificador de Discord que no es válido.`);
198				}
199				break;
200			}
201	
202			case "select": {
203				const allowed = new Set((param.options ?? []).map((o) => o.value));
204				const values = param.multiple ? value : [value];
205				if (param.multiple && !Array.isArray(value)) {
206					fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
207					break;
208				}
209				for (const v of values as unknown[]) {
210					if (typeof v !== "string" || !allowed.has(v)) {
211						fail("unknown_option", `«${param.label}» tiene un valor que no está entre las opciones.`);
212						break;
213					}
214				}
215				break;
216			}
217	
218			case "image_canvas": {
219				if (typeof value !== "object" || Array.isArray(value)) {
220					fail("invalid_type", `«${param.label}» tiene que ser un lienzo.`);
221					break;
222				}
223				const canvas = value as Record<string, unknown>;
224				if (typeof canvas.width !== "number" || typeof canvas.height !== "number") {
225					fail("invalid_type", `«${param.label}» necesita un ancho y un alto numéricos.`);
226				}
227				if (!Array.isArray(canvas.elements)) {
228					fail("invalid_type", `«${param.label}» necesita una lista de elementos.`);
229				}
230				break;
231			}
232		}
233	
234		return issues;
235	}
236	
237	/** Valida el objeto `params` de un bloque contra la especificación del catálogo. */
238	export function validateParams(
239		params: Record<string, unknown> | undefined,
240		spec: AutomationParam[],
241		path: string
242	): AutomationIssue[] {
243		const values = params ?? {};
244		return spec.flatMap((param) => checkOne(param, values[param.key], path));
245	}
246	
247	// ─── Automatización completa ──────────────────────────────────────────────────
248	
249	/**
250	 * Valida una automatización entera. Lista vacía = se puede publicar.
251	 *
252	 * El orden importa: si el disparador no se reconoce se para ahí, porque sin
253	 * saber qué contexto aporta, todos los errores de contexto de abajo serían ruido
254	 * derivado del primero.
255	 */
256	export function validateAutomation(automation: DBAutomation): AutomationIssue[] {
257		const issues: AutomationIssue[] = [];
258	
259		if (!automation.name?.trim()) {
260			issues.push({ path: "name", code: "empty_name", message: "La automatización necesita un nombre." });
261		}
262	
263		const triggerType = automation.trigger?.type;
264		if (!triggerType || !isAutomationTriggerType(triggerType)) {
265			issues.push({
266				path: "trigger.type",
267				code: "unknown_trigger",
268				message: "Ese disparador no existe. Puede que se haya retirado del catálogo."
269			});
270			return issues;
271		}
272	
273		const trigger = AUTOMATION_TRIGGERS[triggerType];
274		const provided = new Set<AutomationContextKey>(trigger.provides);
275		issues.push(...validateParams(automation.trigger.params, trigger.params, "trigger.params"));
276	
277		issues.push(...validateConditionList(automation.conditions, provided, "conditions"));
278	
279		if (!automation.actions || automation.actions.length === 0) {
280			issues.push({ path: "actions", code: "no_actions", message: "Añade al menos una acción." });
281		}
282		issues.push(...validateActionList(automation.actions, provided, "actions"));
283	
284		// ── Ramas alternativas ────────────────────────────────────────────────────
285	
286		// Sin condición en la raíz, la raíz NUNCA falla: se ejecuta siempre, así que
287		// ninguna rama llegaría a mirarse jamás. Se corta aquí, antes de recorrerlas
288		// una a una, en vez de dejar que cada rama parezca válida por separado.
289		if ((automation.branches?.length ?? 0) > 0 && (automation.conditions?.length ?? 0) === 0) {
290			issues.push({
291				path: "branches",
292				code: "unreachable_branch",
293				message:
294					"Las ramas sólo tienen sentido con una condición arriba: sin ella el flujo principal se ejecuta siempre y ninguna rama llega a evaluarse."
295			});
296		}
297	
298		const branches = automation.branches ?? [];
299		branches.forEach((branch, index) => {
300			const at = `branches[${index}]`;
301	
302			issues.push(...validateConditionList(branch.conditions, provided, `${at}.conditions`));
303	
304			if (!branch.actions || branch.actions.length === 0) {
305				issues.push({
306					path: `${at}.actions`,
307					code: "no_actions",
308					message: "Esta rama no hace nada: añade una acción o quítala."
309				});
310			}
311			issues.push(...validateActionList(branch.actions, provided, `${at}.actions`));
312	
313			// Una rama SIN condiciones es el «si no» final: pasa siempre, así que todo
314			// lo que venga detrás no se ejecutará jamás. Se rechaza al guardar en vez
315			// de dejar al usuario descubriendo en producción por qué su última rama no
316			// hace nada.
317			//
318			// El mensaje habla de la vía que FALTA por rellenar y no de la colocación,
319			// porque es el estado normal de una vía «si no, si…» recién abierta: nace
320			// sin condición, delante del «si no», y lo siguiente que hay que hacer es
321			// justo ponérsela.
322			const isElse = (branch.conditions?.length ?? 0) === 0;
323			if (isElse && index !== branches.length - 1) {
324				issues.push({
325					path: `${at}.conditions`,
326					code: "unreachable_branch",
327					message:
328						"Esta vía necesita una condición: «si no» es siempre la última, y lo que va detrás de ella no se ejecuta nunca."
329				});
330			}
331		});
332	
333		return issues;
334	}
335	
336	/** Valida una lista de condiciones contra el contexto del disparador. */
337	function validateConditionList(
338		conditions: DBAutomation["conditions"] | undefined,
339		provided: Set<AutomationContextKey>,
340		pathPrefix: string
341	): AutomationIssue[] {
342		const issues: AutomationIssue[] = [];
343		conditions?.forEach((condition, index) => {
344			const at = `${pathPrefix}[${index}]`;
345			if (!isAutomationConditionType(condition.type)) {
346				issues.push({ path: `${at}.type`, code: "unknown_condition", message: "Esa condición no existe." });
347				return;
348			}
349			const def = AUTOMATION_CONDITIONS[condition.type];
350			const missing = def.requires.filter((k) => !provided.has(k));
351			if (missing.length > 0) {
352				issues.push({
353					path: `${at}.type`,
354					code: "context_missing",
355					message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`
356				});
357			}
358			if (condition.negate && !def.negatable) {
359				issues.push({
360					path: `${at}.negate`,
361					code: "not_negatable",
362					message: `«${def.label}» no se puede invertir.`
363				});
364			}
365			issues.push(...validateParams(condition.params, def.params, `${at}.params`));
366		});
367		return issues;
368	}
369	
370	/** Valida una lista de acciones contra el contexto del disparador. */
371	function validateActionList(
372		actions: DBAutomation["actions"] | undefined,
373		provided: Set<AutomationContextKey>,
374		pathPrefix: string
375	): AutomationIssue[] {
376		const issues: AutomationIssue[] = [];
377		actions?.forEach((action, index) => {
378			const at = `${pathPrefix}[${index}]`;
379			if (!isAutomationActionType(action.type)) {
380				issues.push({ path: `${at}.type`, code: "unknown_action", message: "Esa acción no existe." });
381				return;
382			}
383			const def = AUTOMATION_ACTIONS[action.type];
384			const missing = def.requires.filter((k) => !provided.has(k));
385			if (missing.length > 0) {
386				issues.push({
387					path: `${at}.type`,
388					code: "context_missing",
389					message: `«${def.label}» no se puede usar con este disparador: le falta ${missing.join(", ")}.`
390				});
391			}
392			issues.push(...validateParams(action.params, def.params, `${at}.params`));
393		});
394		return issues;
395	}
