284			const byMode = AUTOMATION_EXECUTION_MODES.flatMap((mode) => triggersForMode(mode));
285			expect(byMode.map((t) => t.key).sort()).toEqual([...AUTOMATION_TRIGGER_KEYS].sort());
286		});
287	});
288	
289	describe("acciones de estadística", () => {
290		it("count_voice_members, count_members y count_role_members guardan su dato con el patrón compartido de save_as", () => {
291			for (const key of ["count_voice_members", "count_members", "count_role_members"] as const) {
292				const saveAs = AUTOMATION_ACTIONS[key].params.find((p) => p.key === "save_as");
293				expect(saveAs, key).toBeDefined();
294				expect(saveAs?.pattern, key).toBe("^[a-z0-9_]{1,32}$");
295				expect(saveAs?.required, key).toBe(true);
296			}
297		});
298	
299		it("count_role_members declara roles, scope y save_as en ese orden, y se puede reintentar", () => {
300			const def = AUTOMATION_ACTIONS.count_role_members;
301			expect(def.params.map((p) => p.key)).toEqual(["roles", "scope", "save_as"]);
302	
303			const roles = def.params.find((p) => p.key === "roles");
304			expect(roles?.type).toBe("role_list");
305			expect(roles?.required).toBe(true);
306	
307			const scope = def.params.find((p) => p.key === "scope");
308			expect(scope?.type).toBe("select");
309			expect(scope?.required).toBe(true);
310			expect(scope?.default).toBe("guild");
311			// Exactamente las tres opciones del contrato — ni una de más ni de menos.
312			// El motor las distingue por su `value`: cambiar uno aquí sin tocar
313			// `ActionRunner` deja el contador midiendo otra cosa en silencio.
314			expect(scope?.options).toEqual([
315				{ value: "guild", label: "En todo el servidor" },
316				{ value: "voice", label: "Sólo los conectados a voz" },
317				{ value: "online", label: "Sólo los que están en línea" }
318			]);
319	
320			// Sólo lee la caché: reintentarla tras un 429 no puede duplicar nada.
321			expect(RETRYABLE_ACTIONS.has("count_role_members")).toBe(true);
322		});
323	});
324	
325	describe("flowVariables", () => {
326		it("ignora las acciones sin save_as y no repite variables", () => {
327			const actions: Array<{ type: string; params?: Record<string, unknown> }> = [
328				{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
329				{ type: "send_message", params: { channel: "1", content: "hola" } },
330				{ type: "count_voice_members", params: { save_as: "personas_en_voz" } },
331				{ type: "count_members", params: { save_as: "miembros" } }
332			];
333			expect(flowVariables(actions)).toEqual(["personas_en_voz", "miembros"]);
334		});
335	
336		it("sin ninguna acción con save_as no hay variables de flujo", () => {
337			expect(flowVariables([{ type: "send_message", params: { channel: "1", content: "hola" } }])).toEqual([]);
338		});
339	});
