	},

	voice_count_changed: {
		key: "voice_count_changed",
		category: "stats",
		label: "Entre o salga alguien de un canal de voz",
		description:
			"Cada vez que cambia cuánta gente hay en voz, con {voice_count}. Salta con CADA movimiento; para un canal contador suele bastar «Cada 5 minutos», que además respeta mejor el límite de renombrado de Discord.",
		events: ["VOICE_STATE_UPDATE"],
		provides: ["voice"],
		params: []
	},

	member_join: {
		key: "member_join",
		category: "member",
		label: "Entre al servidor",
		description: "Alguien se une al servidor.",
		events: ["GUILD_MEMBER_ADD"],
		provides: ["user", "member"],
		params: []
	},

	member_leave: {
		key: "member_leave",
		category: "member",
		label: "Salga del servidor",
		description: "Alguien se va del servidor, lo expulsan o lo banean.",
		events: ["GUILD_MEMBER_REMOVE"],
		// Al salir, Discord ya no manda la ficha de miembro: sólo el usuario.
		provides: ["user"],
		params: []
	},

	member_role_add: {
		key: "member_role_add",
		category: "member",
		label: "Reciba un rol",
		description: "A alguien le dan un rol.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member", "role"],
		params: [roleFilterParam("Sólo estos roles")]
	},

	member_role_remove: {
		key: "member_role_remove",
		category: "member",
		label: "Pierda un rol",
		description: "A alguien le quitan un rol.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member", "role"],
		params: [roleFilterParam("Sólo estos roles")]
	},

	member_nickname_change: {
		key: "member_nickname_change",
		category: "member",
		label: "Cambie su apodo",
		description: "Alguien se cambia el apodo en este servidor.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member"],
		params: []
	},

	member_profile_change: {
		key: "member_profile_change",
		category: "member",
		label: "Cambie su avatar o su nombre",
		description: "Alguien cambia su perfil global de Discord.",
		// `GUILD_MEMBER_UPDATE` y NO `USER_UPDATE`: aquél sólo salta para el
		// PROPIO BOT. Con `USER_UPDATE` este disparador salía en el panel, se podía
		// publicar y no se disparaba nunca con ningún miembro — el fallo más caro
		// de este catálogo, porque no hay error que lo delate.
		//
		// Los cambios de perfil de otros llegan dentro del `user` de
		// `GUILD_MEMBER_UPDATE`, comparando contra la foto de Redis igual que los
		// roles y el apodo.
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member"],
		params: []
	},

	/**
	 * Etiqueta de servidor (`primary_guild` del objeto `user`).
	 *
	 * Discord la expone con `identity_guild_id`, `identity_enabled` y `tag`, así
	 * que se detecta comparando la foto. Lo que NO expone —y por eso no hay
	 * disparador— es la BIO: el objeto `User` de la API no tiene ese campo para
	 * los bots, ni por gateway ni por REST. No es difícil, es imposible.
	 */
	member_tag_add: {
		key: "member_tag_add",
		category: "member",
		label: "Se ponga la etiqueta de un servidor",
		description: "Empieza a mostrar la etiqueta de un servidor en su perfil.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member"],
		params: [
			{
				key: "guild",
				type: "text",
				required: false,
				label: "ID del servidor",
				hint: "Vacío = la de este servidor. Pon un id sólo si quieres vigilar la etiqueta de OTRO servidor.",
				default: ""
			}
		]
	},

	member_tag_remove: {
		key: "member_tag_remove",
		category: "member",
		label: "Se quite la etiqueta de un servidor",
		description: "Deja de mostrar la etiqueta que llevaba.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member"],
		params: [
			{
				key: "guild",
				type: "text",
				required: false,
				label: "ID del servidor",
				hint: "Vacío = la de este servidor. Pon un id sólo si quieres vigilar la de otro.",
				default: ""
			}
		]
	},

	/**
	 * Estado personalizado: el textito que sale AL LADO DEL NOMBRE.
	 *
	 * No confundirlo con la BIO («Sobre mí»): aquélla los bots no la ven, ni por
	 * gateway ni por REST — es privada por decisión de Discord y no hay
	 * disparador posible (ver la nota de `member_tag_add`). El estado
	 * personalizado sí es público y viaja en `PRESENCE_UPDATE`, dentro de
	 * `activities` como la actividad de tipo 4, en su campo `state`.
	 *
	 * Es el par con el que se monta el clásico «pon la invitación en tu estado y
	 * te doy un rol»: uno lo da al ponerlo y el otro lo retira al quitarlo.
	 *
	 * OJO: `PRESENCE_UPDATE` exige el intent PRIVILEGIADO de presencias, que a
	 * partir de 100 servidores aprueba Discord a mano. Sin él estos dos
	 * disparadores se publican y no saltan nunca — el módulo no puede saberlo, y
	 * es la razón de que el texto lo diga.
	 */
	member_status_add: {
		key: "member_status_add",
		category: "member",
		label: "Ponga algo en su estado",
		description:
			"Empieza a llevar cierto texto en su estado personalizado, el de al lado del nombre. Requiere el permiso de presencias.",
		events: ["PRESENCE_UPDATE"],
		provides: ["user", "member"],
		params: [
			{
				key: "text",
				type: "text",
				required: false,
				label: "Texto que tiene que llevar",
				hint: "Se busca dentro del estado, sin distinguir mayúsculas. Vacío = cualquier estado.",
				default: ""
			}
		]
	},

	member_status_remove: {
		key: "member_status_remove",
		category: "member",
		label: "Se quite algo del estado",
		description:
			"Deja de llevar ese texto en su estado personalizado. Es el complementario del anterior: con los dos, el rol se da y se retira solo.",
		events: ["PRESENCE_UPDATE"],
		provides: ["user", "member"],
		params: [
			{
				key: "text",
				type: "text",
				required: false,
				label: "Texto que dejó de llevar",
				hint: "El mismo que pusiste en el disparador de ponerlo. Vacío = se quedó sin estado.",
				default: ""
			}
		]
	},

	member_boost: {
		key: "member_boost",
		category: "member",
		label: "Empiece a mejorar el servidor",
		description: "Alguien aporta un boost al servidor.",
		events: ["GUILD_MEMBER_UPDATE"],
		provides: ["user", "member"],
		params: []
	},

	member_banned: {
		key: "member_banned",
		category: "member",
		label: "Sea baneado",
		description: "Alguien recibe un baneo del servidor.",
		events: ["GUILD_BAN_ADD"],
		provides: ["user"],
		params: []
	},

	member_unbanned: {
		key: "member_unbanned",
		category: "member",
		label: "Sea desbaneado",
		description: "A alguien le retiran el baneo.",
		events: ["GUILD_BAN_REMOVE"],
		provides: ["user"],
		params: []
	},

	// ─── Mensajes ───────────────────────────────────────────────────────────────

	message_send: {
		key: "message_send",
		category: "message",
		label: "Envíe un mensaje",
		description: "Alguien escribe un mensaje en el servidor.",
		events: ["MESSAGE_CREATE"],
		provides: ["user", "member", "channel", "message"],
		params: []
	},

	message_edit: {
		key: "message_edit",
		category: "message",
		label: "Edite un mensaje",
		description: "Alguien edita un mensaje que ya había enviado.",
		events: ["MESSAGE_UPDATE"],
		provides: ["user", "member", "channel", "message"],
		params: []
	},

	message_delete: {
		key: "message_delete",
		category: "message",
		label: "Borre un mensaje",
		description: "Se borra un mensaje del servidor.",
		events: ["MESSAGE_DELETE"],
		// Discord manda sólo los IDs al borrar: no hay autor ni contenido.
		provides: ["channel", "message"],
		params: []
	},

	custom_command: {
		key: "custom_command",
		category: "message",
		label: "Use un comando personalizado",
		description: "Alguien escribe el comando que tú elijas, con el prefijo del servidor.",
		events: ["MESSAGE_CREATE"],
		provides: ["user", "member", "channel", "message"],
		params: [
			{
				key: "command",
				type: "text",
				required: true,
				label: "Comando",
				hint: "Sin el prefijo. Ejemplo: escribe «reglas» para que responda a !reglas.",
				min: 1,
				max: 32
			},
			{
				// El prefijo es un parámetro DEL DISPARADOR y no el del servidor a
				// propósito: resolverlo desde la config del guild obligaría a una
				// lectura extra en CADA mensaje del servidor, que es el camino más
				// caliente del módulo. Aquí es explícito, cuesta cero y además deja
				// tener comandos con prefijos distintos.
				key: "prefix",
				type: "text",
				required: true,
				label: "Prefijo",
				hint: "El carácter que va delante. Por defecto «!».",
				min: 1,
				max: 5,
				default: "!"
			}
		]
	},

	reaction_add: {
		key: "reaction_add",
		category: "message",
		label: "Reaccione a un mensaje",
		description: "Alguien añade una reacción.",
		events: ["MESSAGE_REACTION_ADD"],
		provides: ["user", "member", "channel", "message", "emoji"],
		params: [emojiFilterParam]
	},

	reaction_remove: {
		key: "reaction_remove",
		category: "message",
		label: "Quite una reacción",
		description: "Alguien retira una reacción.",
		events: ["MESSAGE_REACTION_REMOVE"],
		provides: ["user", "member", "channel", "message", "emoji"],
		params: [emojiFilterParam]
	},

	// ─── Voz e hilos ────────────────────────────────────────────────────────────

	voice_join: {
		key: "voice_join",
		category: "voice",
		label: "Entre a un canal de voz",
		description: "Alguien se conecta a un canal de voz.",
		events: ["VOICE_STATE_UPDATE"],
		provides: ["user", "member", "voice"],
		params: []
	},

	voice_leave: {
		key: "voice_leave",
		category: "voice",
		label: "Salga de un canal de voz",
		description: "Alguien se desconecta de un canal de voz.",
		events: ["VOICE_STATE_UPDATE"],
		provides: ["user", "member", "voice"],
		params: []
	},

	voice_move: {
		key: "voice_move",
		category: "voice",
		label: "Cambie de canal de voz",
		description: "Alguien pasa de un canal de voz a otro.",
		events: ["VOICE_STATE_UPDATE"],
		provides: ["user", "member", "voice"],
		params: []
	},

	thread_join: {
		key: "thread_join",
		category: "voice",
		label: "Se una a un hilo",
		description: "Alguien entra en un hilo.",
		events: ["THREAD_MEMBERS_UPDATE"],
		provides: ["user", "thread"],
		params: []
	},

	// ─── Servidor ───────────────────────────────────────────────────────────────

	channel_create: {
		key: "channel_create",
		category: "server",
		label: "Se cree un canal",
		description: "Se añade un canal al servidor.",
		events: ["CHANNEL_CREATE"],
		provides: ["channel"],
		params: []
	},

	channel_delete: {
		key: "channel_delete",
		category: "server",
		label: "Se borre un canal",
		description: "Se elimina un canal del servidor.",
		events: ["CHANNEL_DELETE"],
		provides: ["channel"],
		params: []
	},

	role_create: {
		key: "role_create",
		category: "server",
		label: "Se cree un rol",
		description: "Se añade un rol al servidor.",
		events: ["ROLE_CREATE"],
		provides: ["role"],
		params: []
	},

	role_delete: {
		key: "role_delete",
		category: "server",
		label: "Se borre un rol",
		description: "Se elimina un rol del servidor.",
		events: ["ROLE_DELETE"],
		provides: ["role"],
		params: []
	},

	// `member_activity` sólo aporta `user` + `member`, nunca `message` ni `voice`:
	// es el mínimo común de las seis señales que lo alimentan (hablar, editar,
	// reaccionar, entrar a voz, unirse a un hilo...). Prometer más sería ofrecer
	// acciones que a veces no tendrían con qué correr — «borra el mensaje», por
	// ejemplo, cuando lo que disparó todo fue que alguien entrase a un canal de voz.
	//
	// Salta MUCHÍSIMO: literalmente, cada mensaje de cada miembro. Para eso existe
	// la condición «límite de frecuencia» (`rate_limit`) — sin ella, cualquier
	// automatización con este disparador se dispara sin parar.
	member_activity: {
		key: "member_activity",
		category: "server",
		label: "Haga algo un miembro",
		description:
			"Cualquier señal que le llega al bot de un miembro: que hable, edite, reaccione, entre a voz o se una a un hilo. Para comprobar algo al vuelo —cuánto lleva en el servidor, qué roles tiene— y actuar.",
		events: [
			"MESSAGE_CREATE",
			"MESSAGE_UPDATE",
			"MESSAGE_REACTION_ADD",
			"MESSAGE_REACTION_REMOVE",
			"VOICE_STATE_UPDATE",
			"THREAD_MEMBERS_UPDATE"
		],
		provides: ["user", "member"],
		params: [
			{
				key: "sources",
				type: "select",
				multiple: true,
				required: false,
				label: "Sólo con estas señales",
				hint: "Vacío = cualquier cosa que haga el miembro.",
				default: [],
				options: [
					{ value: "message", label: "Escriba o edite un mensaje" },
					{ value: "reaction", label: "Reaccione a un mensaje" },
					{ value: "voice", label: "Entre, salga o cambie de canal de voz" },
					{ value: "thread", label: "Se una a un hilo" }
				]
			}
		]
	}
};

/**
 * Todos los eventos de Discord que el módulo necesita escuchar, sin repetidos.
 *
 * El `events: [...]` del constructor se construye CON ESTO, no a mano: añadir un
 * disparador que estrene evento y olvidarse de declararlo deja el handler mudo
 * sin ningún error, y es de los fallos más caros de encontrar del SDK.
 */
export const AUTOMATION_REQUIRED_EVENTS: AutomationDispatchEvent[] = [
	...new Set(Object.values(AUTOMATION_TRIGGERS).flatMap((trigger) => trigger.events))
];

