// ─── Modo de ejecución ──────────────────────────────────────────────────────

/**
 * Cuándo se ejecuta el flujo — la primera pregunta del editor nuevo, antes
 * incluso de elegir el disparador: «todo el rato» | «cada cierto tiempo» | «a
 * una hora fija».
 *
 * NO es un campo de `DBAutomation`: se DERIVA del disparador elegido. Guardarlo
 * aparte pediría una migración y, peor, dejaría existir un estado imposible que
 * alguien tendría que arbitrar en ejecución — por ejemplo un `on_interval`
 * guardado con modo `always`, que contradice a su propio disparador.
 */
export const AUTOMATION_EXECUTION_MODES = ["always", "interval", "schedule"] as const;
export type AutomationExecutionMode = (typeof AUTOMATION_EXECUTION_MODES)[number];

/**
 * Modo al que pertenece un disparador. Se mira por su CLAVE y no por su
 * `category`: `on_schedule` y `on_interval` comparten la categoría `schedule`
 * (a los dos los despierta el poller, no un evento de Discord) y es justo el
 * modo el que los separa.
 */
export function executionModeOf(trigger: AutomationTriggerType): AutomationExecutionMode {
	switch (trigger) {
		case "on_interval":
			return "interval";
		case "on_schedule":
			return "schedule";
		default:
			return "always";
	}
}

/**
 * Disparadores de un modo, en el orden de `AUTOMATION_TRIGGER_KEYS`. `interval`
 * y `schedule` traen uno solo: elegir el modo ya elige el disparador, sin
 * segundo paso.
 */
export function triggersForMode(mode: AutomationExecutionMode): AutomationTriggerDef[] {
	return AUTOMATION_TRIGGER_KEYS.filter((key) => executionModeOf(key) === mode).map((key) => AUTOMATION_TRIGGERS[key]);
}

