		// pedido —el canal que muestra «Miembros: 1.234», que nace de un
		// `member_join`— era IMPOSIBLE de montar. El canal se elige aquí.
		requires: [],
		permission: "ManageChannels",
		params: [
			{
				key: "channel",
				type: "channel",
				required: false,
				label: "Canal",
				hint: "Vacío = el canal donde ocurrió, si el disparador trae uno.",
				default: ""
			},
			{
				key: "name",
				type: "text",
				required: true,
				label: "Nombre",
				// El aviso del límite va aquí porque es la sorpresa más cara de esta
				// acción: Discord sólo admite 2 cambios de nombre por canal cada 10
				// minutos, así que un canal contador NO se actualiza al instante.
				// El módulo lo respeta solo (`claimChannelRename`), pero quien lo
				// configura tiene que saberlo o lo dará por roto.
				hint: "Admite variables: «Miembros: {member_count}». Discord sólo deja renombrar un canal 2 veces cada 10 minutos, así que se actualiza como mucho cada 10 minutos.",
				max: 100,
				supportsVariables: true
			}
		]
	},

	set_slowmode: {
		key: "set_slowmode",
		category: "server",
		label: "Poner modo lento",
		description: "Limita cada cuánto se puede escribir en el canal.",
		requires: ["channel"],
		permission: "ManageChannels",
		params: [
			{
				key: "seconds",
				type: "number",
				required: true,
				label: "Segundos entre mensajes",
				hint: "0 desactiva el modo lento. El máximo de Discord son 6 horas.",
				min: 0,
				max: 21_600,
				default: 5
			}
		]
	},

	set_channel_permission: {
		key: "set_channel_permission",
		category: "server",
		label: "Cambiar permisos de un canal",
		description: "Permite o deniega un permiso a un rol en un canal.",
		requires: [],
		permission: "ManageRoles",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{ key: "role", type: "role", required: true, label: "Rol" },
			{
				key: "permission",
				type: "select",
				required: true,
				label: "Permiso",
				default: "SendMessages",
				options: [
					{ value: "ViewChannel", label: "Ver el canal" },
					{ value: "SendMessages", label: "Enviar mensajes" },
					{ value: "AddReactions", label: "Añadir reacciones" },
					{ value: "Connect", label: "Conectarse (voz)" },
					{ value: "Speak", label: "Hablar (voz)" }
				]
			},
			{
				key: "mode",
				type: "select",
				required: true,
				label: "Ponerlo en",
				default: "deny",
				options: [
					{ value: "allow", label: "Permitido" },
					{ value: "deny", label: "Denegado" },
					{ value: "inherit", label: "Heredado" }
				]
			}
		]
	},

	// ─── Voz ────────────────────────────────────────────────────────────────────

	move_voice: {
		key: "move_voice",
		category: "voice",
		label: "Mover a otro canal de voz",
		description: "Sólo funciona si la persona está conectada a voz.",
		requires: ["member"],
		permission: "MoveMembers",
		params: [
			{
				key: "channel",
				type: "channel",
				required: false,
				label: "Canal de destino",
				hint: "Déjalo vacío para desconectarla de la voz.",
				default: null
			}
		]
	},

	voice_mute: {
		key: "voice_mute",
		category: "voice",
		label: "Silenciar en voz",
		description: "Silencio de servidor. Sólo funciona si está conectada a voz.",
		requires: ["member"],
		permission: "MuteMembers",
		params: [
			{
				key: "mute",
				type: "boolean",
				required: true,
				label: "Silenciar",
				hint: "Desactivado, le quita el silencio.",
				default: true
			}
		]
	},

	// ─── Estadísticas ───────────────────────────────────────────────────────────
	//
	// No actúan sobre Discord —no hay canal que renombrar ni rol que dar—: leen
	// un número y lo guardan en una variable de flujo (`save_as`) para que las
	// acciones de detrás lo usen en sus campos de texto. Por eso no llevan
	// `permission`. Son las dos únicas de esta familia: las que tienen un dato
	// real detrás.

	count_voice_members: {
		key: "count_voice_members",
		category: "stats",
		label: "Contar personas en voz",
		description: "Cuenta cuánta gente hay en un canal de voz, o en todo el servidor.",
		requires: [],
		params: [
			{
				key: "channel",
				type: "channel",
				required: false,
				label: "Canal de voz",
				hint: "Vacío = todos los canales de voz del servidor."
			},
			saveAsParam("personas_en_voz")
		]
	},

	count_members: {
		key: "count_members",
		category: "stats",
		label: "Contar miembros del servidor",
		description: "El total de miembros, para un canal contador o un aviso de hito.",
		requires: [],
		params: [saveAsParam("miembros")]
	},

	count_role_members: {
		key: "count_role_members",
		category: "stats",
		label: "Contar personas con un rol",
		description: "Cuenta cuánta gente tiene alguno de los roles que elijas: en todo el servidor o sólo la conectada a voz.",
		requires: [],
		params: [
			{
				key: "roles",
				type: "role_list",
				required: true,
				label: "Roles",
				hint: "Cuenta a quien tenga ALGUNO de estos roles."
			},
			{
				key: "scope",
				type: "select",
				required: true,
				label: "Dónde contar",
				default: "guild",
				options: [
					{ value: "guild", label: "En todo el servidor" },
					{ value: "voice", label: "Sólo los conectados a voz" }
				]
			},
			saveAsParam("personas_con_rol")
		]
	},

	/**
	 * Se metió primero como tercera opción del `scope` de `count_role_members`,
	 * defendiendo que era la misma pregunta con otro filtro. Estaba mal: una
	 * opción escondida dentro de un desplegable de OTRA acción no se encuentra
	 * escaneando el catálogo, que es como se busca aquí, y quien la pedía no la
	 * veía por ningún lado. Necesita su propia tarjeta.
	 *
	 * `PRESENCE_UPDATE` exige el intent PRIVILEGIADO de presencias, igual que
	 * `member_status_add` (ver su nota en `triggers.ts`): sin él, el bot nunca ha
	 * visto conectarse a nadie y esto cuenta cero. El módulo no puede saberlo, y
	 * es la razón de que el aviso vaya en la descripción.
	 */
	count_online_members: {
		key: "count_online_members",
		category: "stats",
		label: "Contar miembros conectados",
		description:
			"Cuenta cuánta gente del servidor está en línea ahora mismo. Necesita el permiso de presencias, y cuenta a quien el bot haya visto conectarse desde que arrancó.",
		requires: [],
		params: [saveAsParam("miembros_conectados")]
	},

	// ─── Flujo ──────────────────────────────────────────────────────────────────

	wait: {
		key: "wait",
		category: "flow",
		label: "Esperar",
		description: "Pausa antes de seguir con la acción siguiente.",
		requires: [],
		params: [
			{
				key: "seconds",
				type: "number",
				required: true,
				label: "Segundos",
				// Techo bajo a propósito: la espera ocupa la ejecución entera, y una
				// espera larga multiplicada por muchos disparos ahoga el módulo.
				hint: "Como mucho 5 minutos.",
				min: 1,
				max: 300,
				default: 5
			}
		]
	},

	counter_set: {
		key: "counter_set",
		category: "flow",
		label: "Cambiar un contador",
		description: "Lleva la cuenta de algo para usarla luego en una condición.",
		requires: [],
		params: [
			{ key: "counter", type: "counter", required: true, label: "Contador", min: 1, max: 64 },
			{
				key: "scope",
				type: "select",
				required: true,
				label: "Se cuenta por",
				default: "user",
				options: [
					{ value: "user", label: "Cada usuario" },
					{ value: "channel", label: "Cada canal" },
					{ value: "guild", label: "Todo el servidor" }
				]
			},
			{
				key: "operation",
				type: "select",
				required: true,
				label: "Operación",
				default: "add",
				options: [
					{ value: "add", label: "Sumar" },
					{ value: "subtract", label: "Restar" },
					{ value: "set", label: "Fijar a" },
					{ value: "reset", label: "Poner a cero" }
				]
			},
			{ key: "value", type: "number", required: false, label: "Valor", min: 0, default: 1 }
		]
	},

	run_automation: {
		key: "run_automation",
		category: "flow",
		label: "Ejecutar otra automatización",
		description: "Encadena otra automatización con el mismo contexto.",
		requires: [],
		params: [{ key: "automation", type: "automation", required: true, label: "Automatización" }]
	}
};

/**
 * Acciones que es SEGURO reintentar cuando Discord contesta con un 429.
 *
 * El criterio es la idempotencia, no la importancia: aplicar dos veces «dale el
 * rol X» deja exactamente el mismo estado que aplicarla una, así que reintentar
 * no puede hacer daño. Enviar un mensaje NO lo es — el reintento publica un
 * segundo mensaje, el usuario recibe el mismo aviso dos veces y no hay forma de
 * recogerlo.
 *
 * Por eso la lista es una ALTA EXPLÍCITA y no una exclusión: al añadir una
 * acción nueva al catálogo, lo seguro por defecto es no reintentarla. Si fuese
 * una lista de excluidas, olvidarse de dar de alta la acción nueva la haría
 * reintentable en silencio, que es el fallo caro.
 *
 * `wait`, `counter_set` y `run_automation` no salen a la red, así que no pueden
 * dar 429 y no pintan nada aquí.
 */
export const RETRYABLE_ACTIONS: ReadonlySet<AutomationActionType> = new Set([
	"add_reaction",
	"pin_message",
	// Idempotente por el lado de Discord: al segundo intento contesta 40033
	// («ya estaba publicado») y el ejecutor lo lee como éxito, así que un
	// reintento no puede publicar dos veces.
	"crosspost_message",
	"add_role",
	"remove_role",
	"set_nickname",
	"timeout_member",
	"set_slowmode",
	"set_channel_permission",
	"move_voice",
	"voice_mute",
	// Sólo leen: repetir «cuenta la gente en voz», «cuenta los miembros» o
	// «cuenta quién tiene un rol» dos veces deja exactamente el mismo estado
	// que una, así que reintentar no puede hacer daño.
	"count_voice_members",
	"count_members",
	"count_role_members"
]);

/** ¿Se puede reintentar esta acción sin duplicar efectos? */
export const isRetryableAction = (type: string): boolean =>
	RETRYABLE_ACTIONS.has(type as AutomationActionType);

