import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

export const AUTOMATION_ACTIONS: Record<AutomationActionType, AutomationActionDef> = {
	// ─── Mensajería ─────────────────────────────────────────────────────────────

	send_message: {
		key: "send_message",
		category: "message",
		label: "Enviar un mensaje",
		description: "Publica un mensaje en el canal que elijas.",
		requires: [],
		permission: "SendMessages",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{
				// Mismo juego de modos que el mensaje de bienvenida, y con los mismos
				// valores: quien ya ha configurado uno reconoce el otro, y el módulo
				// puede compartir criterio en vez de tener dos formas de decir lo mismo.
				key: "mode",
				type: "select",
				// OPCIONAL aunque la interfaz lo rellene siempre: obligarlo
				// invalidaría de golpe cualquier automatización guardada antes de que
				// el campo existiera. Ausente se lee como "plain", que es justo lo que
				// esas hacían.
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" },
					{ value: "image", label: "Texto + imagen" },
					{ value: "embed_image", label: "Embed + imagen" }
				]
			},
			{
				key: "content",
				type: "long_text",
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
			// El conmutador va DELANTE de los dos campos que gobierna: primero se
			// elige cómo se monta la imagen y luego sale el control de ese modo.
			// Los dos campos coexisten en los datos —cambiar de modo no borra el
			// otro—, sólo cambia cuál se pinta.
			{
				key: "image_mode",
				type: "select",
				variant: "chips",
				required: false,
				label: "Imagen",
				default: "basic",
				options: [
					{ value: "basic", label: "Modo básico" },
					{ value: "advanced", label: "Modo avanzado" }
				]
			},
			{
				key: "image_url",
				type: "image",
				required: false,
				label: "Imagen",
				hint: "Se sube al CDN del bot.",
				default: ""
			},
			{ key: "image_canvas", type: "image_canvas", required: false, label: "Lienzo", default: null },
			{ key: "embed_title", type: "text", required: false, label: "Título", max: 256, supportsVariables: true, default: "" },
			{
				key: "embed_description",
				type: "long_text",
				required: false,
				label: "Descripción",
				max: 4000,
				supportsVariables: true,
				default: ""
			},
			{ key: "embed_color", type: "color", required: false, label: "Color", default: null },
			{
				// Autopublicado (crosspost). Sólo Discord sabe si el canal es de
				// ANUNCIOS: en uno de texto normal la llamada falla con 50019, así que
				// el aviso va en el hint y el fallo se reporta como fallo de la acción
				// en vez de tragárselo — quien marca esto quiere que se publique.
				key: "crosspost",
				type: "boolean",
				required: false,
				label: "Autopublicarlo",
				hint: "Sólo en canales de ANUNCIOS: lo publica en los servidores que siguen el canal.",
				default: false
			},
			deleteAfterParam
		]
	},

	send_dm: {
		key: "send_dm",
		category: "message",
		label: "Enviar un mensaje directo",
		description: "Escribe por privado a quien disparó la automatización.",
		// Los MD cerrados hacen fallar la acción, y eso es correcto: se registra y
		// las acciones siguientes continúan.
		requires: ["user"],
		params: [
			// Mismos formatos que «Enviar un mensaje»: un MD también admite embed e
			// imagen, y tener dos acciones de mensaje con capacidades distintas
			// obliga a acordarse de cuál puede qué.
			{
				key: "mode",
				type: "select",
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" },
					{ value: "image", label: "Texto + imagen" },
					{ value: "embed_image", label: "Embed + imagen" }
				]
			},
			{
				key: "content",
